window.MeowWebBundle={"wxml":"<view class=\"app-shell\">\n  <view class=\"status-space\" style=\"height:{{statusBar}}px\"></view>\n  <view class=\"app-header\"><view class=\"brand\"><view class=\"brand-icon\"><image src=\"/assets/paw.png\" /></view><text>喵喵账本</text><view class=\"brand-dot\"></view></view><button class=\"install-button\" bindtap=\"installHelp\"><image src=\"/assets/plus.png\"/><text>放到桌面</text></button></view>\n  <view class=\"account-switch\" aria-label=\"选择账本\"><button class=\"account-option {{account === 'personal' ? 'active' : ''}}\" data-account=\"personal\" bindtap=\"switchAccount\"><image src=\"/assets/cat.png\"/><text>个人消费</text></button><button class=\"account-option {{account === 'public' ? 'active' : ''}}\" data-account=\"public\" bindtap=\"switchAccount\"><image src=\"/assets/book.png\"/><text>公账</text></button></view>\n  <view class=\"main\">\n    <view class=\"page-title-row\"><view><view class=\"eyebrow\">{{tab === 'home' ? 'A LITTLE EVERY DAY' : tab === 'bills' ? 'LIFE IN LITTLE NUMBERS' : tab === 'stats' ? 'KNOW YOUR LITTLE HABITS' : 'YOUR COZY CORNER'}}</view><view class=\"page-title\">{{tab === 'home' ? '把日子，记得可爱一点' : tab === 'bills' ? '每一笔，都算数' : tab === 'stats' ? '看看钱都去哪儿了' : '我的小小账本'}}<text class=\"title-dot\">.</text></view></view></view>\n    <view class=\"month-row\"><view class=\"month-switch\"><view class=\"month-arrow\" bindtap=\"previousMonth\"><image src=\"/assets/arrowLeft.png\"/></view><picker mode=\"date\" fields=\"month\" value=\"{{month}}\" start=\"2000-01\" end=\"2100-12\" bindchange=\"changeMonth\"><view class=\"month-label\">{{vm.monthLabel}}<image src=\"/assets/chevron.png\"/></view></picker><view class=\"month-arrow\" bindtap=\"nextMonth\"><image src=\"/assets/arrow.png\"/></view></view><view class=\"local-badge\"><view></view>仅存本机</view></view>\n    <block wx:if=\"{{tab === 'home'}}\">\n      <view class=\"hero-card\"><view class=\"hero-copy\"><view class=\"hero-label\">本月支出 <view class=\"tiny-dot\"></view></view><view class=\"hero-amount\"><text>¥</text>{{vm.expenseText}}</view><view class=\"hero-message\">认真生活的每一笔，都值得记录。</view></view><image class=\"hero-cat\" src=\"/assets/mascot.png\" mode=\"aspectFit\"/><view class=\"hero-bottom\"><view><text class=\"hero-small-label\">本月收入</text><view class=\"hero-sub-amount\"><text>¥</text> {{vm.incomeText}}</view></view><view class=\"hero-divider\"></view><view><text class=\"hero-small-label\">本月结余</text><view class=\"hero-sub-amount\"><text>¥</text> {{vm.balanceText}}</view></view><view class=\"hero-bottom-paw\"><image src=\"/assets/paw.png\"/></view></view></view>\n      <view class=\"budget-card\" bindtap=\"openBudget\"><view class=\"budget-top\"><view class=\"budget-title\"><image src=\"/assets/wallet.png\"/><text>{{accountName}}预算</text></view><view class=\"budget-remaining {{vm.overBudget ? 'negative' : ''}}\"><block wx:if=\"{{vm.hasBudget}}\">{{vm.overBudget ? '已超支' : '还可花'}} <text>¥ {{vm.remainingText}}</text></block><text wx:else=\"\">设置预算 ›</text><image src=\"/assets/arrow.png\"/></view></view><view class=\"progress-track\"><view class=\"progress-fill {{vm.overBudget ? 'over' : ''}}\" style=\"width:{{vm.budgetPercent}}%\"></view></view><view class=\"budget-meta\"><text>{{vm.hasBudget ? '已用 ' + vm.budgetPercent + '%' : '尚未设置预算'}}</text><text>{{vm.hasBudget ? '月预算 ¥ ' + vm.budgetText : '点击设置当前账本预算'}}</text></view></view>\n      <view class=\"section-heading\"><view>最近账单<text class=\"section-count\">{{vm.count}} 笔</text></view><view class=\"text-link\" bindtap=\"allBills\">查看全部<image src=\"/assets/arrow.png\"/></view></view>\n      <view wx:if=\"{{vm.groups.length === 0}}\" class=\"empty-state\"><image src=\"/assets/empty-cat.png\"/><view class=\"empty-title\">{{vm.isCurrentMonth ? '今天的故事，从第一笔开始' : '这个月，账本还是空白的'}} </view><view class=\"empty-desc\">点下方「＋」，收好生活的小细节</view><button class=\"small-button\" bindtap=\"addEntry\">记下第一笔</button></view>\n      <view class=\"bill-groups\"><block wx:for=\"{{vm.recentGroups}}\" wx:key=\"date\" wx:for-item=\"group\"><view class=\"day-heading\"><view><text class=\"day-label\">{{group.label}}</text><text class=\"day-week\">{{group.weekday}}</text></view><view class=\"day-total\"><text wx:if=\"{{group.expense}}\">支出 {{group.expenseText}}</text><text wx:if=\"{{group.income}}\"> 收入 {{group.incomeText}}</text></view></view><view class=\"bill-card\"><view wx:for=\"{{group.rows}}\" wx:key=\"id\" class=\"bill-row\" data-id=\"{{item.id}}\" bindtap=\"editEntry\"><view class=\"category-icon\" style=\"background:{{item.color}}\"><image src=\"/assets/{{item.icon}}.png\"/></view><view class=\"bill-info\"><view class=\"bill-category\">{{item.categoryName}}</view><view class=\"bill-note\">{{item.note || '生活里的小记录'}}</view></view><view class=\"bill-amount {{item.type === 'income' ? 'income' : ''}}\">{{item.sign}}{{item.displayAmount}}</view></view></view></block></view>\n      <view class=\"daily-note\"><image src=\"/assets/paw.png\"/><text>不必每一笔都完美，记下来就很棒。</text></view>\n    </block>\n    <block wx:elif=\"{{tab === 'bills'}}\">\n      <view class=\"mini-summary\"><view><text>本月支出</text><view>¥ {{vm.expenseText}}</view></view><view><text>本月收入</text><view class=\"income\">¥ {{vm.incomeText}}</view></view></view>\n      <view class=\"search-box\"><image src=\"/assets/search.png\"/><input value=\"{{query}}\" placeholder=\"搜索分类或备注\" bindinput=\"search\" maxlength=\"40\"/></view>\n      <view class=\"filter-row\"><view class=\"filter {{filter === 'all' ? 'active' : ''}}\" data-filter=\"all\" bindtap=\"setFilter\">全部账单</view><view class=\"filter {{filter === 'expense' ? 'active' : ''}}\" data-filter=\"expense\" bindtap=\"setFilter\">只看支出</view><view class=\"filter {{filter === 'income' ? 'active' : ''}}\" data-filter=\"income\" bindtap=\"setFilter\">只看收入</view></view>\n      <view wx:if=\"{{vm.groups.length === 0}}\" class=\"empty-state\"><image src=\"/assets/empty-cat.png\"/><view class=\"empty-title\">{{query ? '没有找到这笔小记录' : '这里还没有账单喵'}} </view><view class=\"empty-desc\">{{query ? '换个关键词试试看' : '换个月份，或记下新的一笔'}}</view></view>\n      <view class=\"bill-groups\"><block wx:for=\"{{vm.groups}}\" wx:key=\"date\" wx:for-item=\"group\"><view class=\"day-heading\"><view><text class=\"day-label\">{{group.label}}</text><text class=\"day-week\">{{group.weekday}}</text></view><view class=\"day-total\"><text wx:if=\"{{group.expense}}\">支出 {{group.expenseText}}</text><text wx:if=\"{{group.income}}\"> 收入 {{group.incomeText}}</text></view></view><view class=\"bill-card\"><view wx:for=\"{{group.rows}}\" wx:key=\"id\" class=\"bill-row\" data-id=\"{{item.id}}\" bindtap=\"editEntry\"><view class=\"category-icon\" style=\"background:{{item.color}}\"><image src=\"/assets/{{item.icon}}.png\"/></view><view class=\"bill-info\"><view class=\"bill-category\">{{item.categoryName}}</view><view class=\"bill-note\">{{item.note || '生活里的小记录'}}</view></view><view class=\"bill-amount {{item.type === 'income' ? 'income' : ''}}\">{{item.sign}}{{item.displayAmount}}</view></view></view></block></view>\n    </block>\n    <block wx:elif=\"{{tab === 'stats'}}\">\n      <view class=\"stats-top\"><view class=\"stat-card\"><image src=\"/assets/bowl.png\"/><text>本月支出</text><view>¥ {{vm.expenseText}}</view></view><view class=\"stat-card sage\"><image src=\"/assets/sun.png\"/><text>日均支出</text><view>¥ {{vm.dailyText}}</view></view></view>\n      <view class=\"chart-card\" wx:if=\"{{vm.isCurrentMonth}}\"><view class=\"section-heading\"><view>近 7 天支出</view><text class=\"subtle\">单位：元</text></view><view class=\"bar-chart\"><view wx:for=\"{{vm.week}}\" wx:key=\"date\" class=\"bar-column\"><view class=\"bar-value\">{{item.amount ? item.amountText : ''}}</view><view class=\"bar-track\"><view class=\"bar {{item.label === '今' ? 'today' : ''}}\" style=\"height:{{item.height}}%\"></view></view><text>{{item.label}}</text></view></view></view>\n      <view class=\"section-heading\"><view>支出排行榜</view><text class=\"subtle\">按分类统计</text></view><view wx:if=\"{{!vm.ranking.length}}\" class=\"empty-state\"><image src=\"/assets/empty-cat.png\"/><view class=\"empty-title\">还没有支出，继续保持喵</view><view class=\"empty-desc\">记录支出后，就能看到分类占比</view></view>\n      <view class=\"ranking-card\" wx:if=\"{{vm.ranking.length}}\"><view wx:for=\"{{vm.ranking}}\" wx:key=\"id\" class=\"rank-row\"><view class=\"category-icon\" style=\"background:{{item.color}}\"><image src=\"/assets/{{item.icon}}.png\"/></view><view class=\"rank-info\"><view class=\"rank-top\"><text>{{item.name}} <text class=\"rank-percent\">{{item.percent}}%</text></text><text>¥ {{item.amountText}}</text></view><view class=\"rank-track\"><view style=\"width:{{item.width}}%;background:{{item.color}}\"></view></view></view></view></view>\n      <view class=\"daily-note\"><image src=\"/assets/spark.png\"/><text>了解自己的小习惯，让每一笔更有方向。</text></view>\n    </block>\n    <block wx:else=\"\">\n      <view class=\"profile-card\"><view class=\"profile-avatar\"><image src=\"/assets/cat.png\"/></view><view><view class=\"profile-name\">认真生活的铲屎官</view><view class=\"profile-desc\">好好记账，慢慢变富。</view></view><view class=\"profile-flower\">✳</view></view>\n      <view class=\"profile-numbers\"><view><view>{{vm.totalCount}}<text> 笔</text></view><text>收好的小记录</text></view><view><view>{{vm.activeDays}}<text> 天</text></view><text>有记录的日子</text></view></view>\n      <view class=\"settings-card\"><view class=\"settings-row\" bindtap=\"openBudget\"><image src=\"/assets/wallet.png\"/><text>月度预算</text><view>¥ {{vm.budgetText}}</view><image class=\"chevron-icon\" src=\"/assets/arrow.png\"/></view><view class=\"settings-row\" bindtap=\"exportBook\"><image src=\"/assets/download.png\"/><text>导出当前账本</text><view>CSV 表格</view><image class=\"chevron-icon\" src=\"/assets/arrow.png\"/></view><view class=\"settings-row\" bindtap=\"showPrivacy\"><image src=\"/assets/shield.png\"/><text>数据与隐私</text><view>本地存储</view><image class=\"chevron-icon\" src=\"/assets/arrow.png\"/></view><view class=\"settings-row\" bindtap=\"clearBook\"><image src=\"/assets/trash.png\"/><text>清空当前账本</text><image class=\"chevron-icon\" src=\"/assets/arrow.png\"/></view></view>\n      <view class=\"profile-footer\"><image src=\"/assets/paw.png\"/><view>喵喵账本</view><text>给认真生活的你 · v{{version}}</text></view>\n    </block>\n  </view>\n  <view class=\"bottom-nav\"><view class=\"nav-item {{tab === 'home' ? 'selected' : ''}}\" data-tab=\"home\" bindtap=\"switchTab\"><image src=\"/assets/home.png\"/><text>首页</text><view class=\"nav-dot\"></view></view><view class=\"nav-item {{tab === 'bills' ? 'selected' : ''}}\" data-tab=\"bills\" bindtap=\"switchTab\"><image src=\"/assets/book.png\"/><text>账单</text><view class=\"nav-dot\"></view></view><button class=\"nav-add\" aria-label=\"记一笔\" hover-class=\"nav-add-pressed\" bindtap=\"addEntry\"><image src=\"/assets/plus.png\"/><text>记一笔</text></button><view class=\"nav-item {{tab === 'stats' ? 'selected' : ''}}\" data-tab=\"stats\" bindtap=\"switchTab\"><image src=\"/assets/chart.png\"/><text>统计</text><view class=\"nav-dot\"></view></view><view class=\"nav-item {{tab === 'mine' ? 'selected' : ''}}\" data-tab=\"mine\" bindtap=\"switchTab\"><image src=\"/assets/cat.png\"/><text>我的</text><view class=\"nav-dot\"></view></view></view>\n  <view wx:if=\"{{editor || budgetEditor}}\" class=\"modal-mask\" bindtap=\"closeEditor\"><view class=\"sheet\" catchtap=\"noop\"><view class=\"sheet-handle\"></view><view class=\"entry-account\"><image src=\"/assets/book.png\"/><text>当前账本 · {{accountName}}</text></view><view class=\"sheet-header\"><view>{{budgetEditor ? '给这个月定个小目标' : form.id ? '编辑这笔小记录' : '记下生活的小事'}}</view><view class=\"close-button\" aria-label=\"关闭记账面板\" bindtap=\"closeEditor\"><image src=\"/assets/close.png\"/></view></view>\n    <block wx:if=\"{{editor}}\"><view class=\"type-switch\"><view class=\"{{form.type === 'expense' ? 'active' : ''}}\" data-type=\"expense\" bindtap=\"setType\">支出</view><view class=\"{{form.type === 'income' ? 'active' : ''}}\" data-type=\"income\" bindtap=\"setType\">收入</view></view><view class=\"amount-input\"><text>¥</text><input type=\"digit\" value=\"{{form.amount}}\" placeholder=\"0.00\" maxlength=\"12\" bindinput=\"inputAmount\" adjust-position=\"{{true}}\"/></view><scroll-view class=\"category-scroll\" scroll-y=\"{{true}}\"><view class=\"category-grid\"><view wx:for=\"{{categories}}\" wx:key=\"id\" class=\"category-option {{form.category === item.id ? 'active' : ''}}\" data-id=\"{{item.id}}\" bindtap=\"setCategory\"><view class=\"category-icon\" style=\"background:{{form.category === item.id ? '#f8d86e' : item.color}}\"><image src=\"/assets/{{item.icon}}.png\"/></view><text>{{item.name}}</text></view></view></scroll-view><picker class=\"date-picker\" mode=\"date\" value=\"{{form.date}}\" start=\"2000-01-01\" end=\"2100-12-31\" bindchange=\"inputDate\"><view class=\"form-row date-row\"><image src=\"/assets/calendar.png\"/><text>日期</text><view class=\"date-value\">{{form.date}}<text class=\"picker-arrow\">›</text></view></view></picker><view class=\"form-row\"><image src=\"/assets/book.png\"/><text>备注</text><input value=\"{{form.note}}\" placeholder=\"为这笔记录加点故事\" maxlength=\"40\" bindinput=\"inputNote\"/></view><button class=\"primary-button\" bindtap=\"saveEntry\">{{form.id ? '保存修改' : '记好啦'}}<image src=\"/assets/paw.png\"/></button><button wx:if=\"{{form.id}}\" class=\"delete-button\" bindtap=\"deleteEntry\">删除这笔记录</button><view wx:else=\"\" class=\"sheet-footnote\">小小一笔，也是在认真生活。</view></block>\n    <block wx:else=\"\"><view class=\"budget-help\">每个月都留一点余地，给生活的小惊喜。<text>仅适用于{{accountName}}的每个月；输入 0 可取消预算。</text></view><view class=\"amount-input\"><text>¥</text><input type=\"digit\" value=\"{{budgetInput}}\" placeholder=\"0.00\" maxlength=\"12\" bindinput=\"inputBudget\"/></view><button class=\"primary-button\" bindtap=\"saveBudget\">就这样定啦<image src=\"/assets/check.png\"/></button></block>\n  </view></view>\n</view>","source":"const L = require('../../utils/ledger');\nPage({\n  data: { tab: 'home', statusBar: 24, month: L.today().slice(0,7), filter: 'all', query: '', vm: {}, categories: [], editor: false, budgetEditor: false, form: {}, budgetInput: '', storageError: false, today: L.today(), version: '1.0.0 网页版', account: 'personal', accountName: '个人消费' },\n  onLoad() {\n    try { const info = typeof wx.getWindowInfo === 'function' ? wx.getWindowInfo() : wx.getSystemInfoSync(); this.setData({ statusBar: info.statusBarHeight || 24 }); } catch (_) {}\n    try {\n      const value = wx.getStorageSync(L.KEY);\n      this.workspace = L.normalizeWorkspace(value);\n      if (value && value.version === 1) wx.setStorageSync(L.KEY, this.workspace);\n    } catch (error) {\n      this.workspace = L.emptyWorkspace(); this.setData({ storageError: true });\n      wx.showModal({ title: '暂时无法读取账本', content: '请重新打开应用后再试。现有缓存不会被覆盖。', showCancel: false });\n    }\n    this.refresh();\n  },\n  onShow() {\n    if (!this.book) return;\n    this.setData({ tab: 'home', editor: false, budgetEditor: false, form: {}, month: L.today().slice(0,7), filter: 'all', query: '' });\n    this.refresh();\n  },\n  refresh() {\n    const account = this.workspace.activeAccount;\n    this.book = this.workspace.accounts[account];\n    this.setData({ account, accountName: L.accountNames[account], vm: L.summary(this.book, this.data.month, this.data.filter, this.data.query), today: L.today() });\n  },\n  commit(book) {\n    if (this.data.storageError) { wx.showToast({ title: '请重新打开应用后再试', icon: 'none' }); return false; }\n    try {\n      const accounts = Object.assign({}, this.workspace.accounts, { [this.data.account]: L.normalize(book) });\n      const next = L.normalizeWorkspace(Object.assign({}, this.workspace, { accounts }));\n      wx.setStorageSync(L.KEY, next); this.workspace = next; this.refresh(); return true;\n    }\n    catch (_) { wx.showToast({ title: '保存失败，请检查设备存储空间', icon: 'none' }); return false; }\n  },\n  switchAccount(e) {\n    const account = e.currentTarget.dataset.account;\n    if (!Object.prototype.hasOwnProperty.call(L.accountNames, account) || account === this.data.account || this.data.editor || this.data.budgetEditor) return;\n    if (this.data.storageError) { wx.showToast({ title: '请重新打开应用后再试', icon: 'none' }); return; }\n    const next = Object.assign({}, this.workspace, { activeAccount: account });\n    try { wx.setStorageSync(L.KEY, next); }\n    catch (_) { wx.showToast({ title: '切换失败，请检查设备存储空间', icon: 'none' }); return; }\n    this.workspace = next;\n    this.setData({ filter: 'all', query: '', form: {} }); this.refresh();\n    wx.pageScrollTo({ scrollTop: 0, duration: 150 });\n  },\n  switchTab(e) { this.setData({ tab: e.currentTarget.dataset.tab, filter: 'all', query: '' }); this.refresh(); wx.pageScrollTo({ scrollTop: 0, duration: 150 }); },\n  allBills() { this.setData({ tab: 'bills', filter: 'all', query: '' }); this.refresh(); wx.pageScrollTo({ scrollTop: 0, duration: 150 }); },\n  changeMonth(e) { this.setData({ month: e.detail.value.slice(0,7) }); this.refresh(); },\n  previousMonth() { this.setData({ month: L.shiftMonth(this.data.month, -1) }); this.refresh(); },\n  nextMonth() { this.setData({ month: L.shiftMonth(this.data.month, 1) }); this.refresh(); },\n  setFilter(e) { this.setData({ filter: e.currentTarget.dataset.filter }); this.refresh(); },\n  search(e) { this.setData({ query: e.detail.value }); this.refresh(); },\n  addEntry() { this.setData({ editor: true, form: { id: '', type: 'expense', category: 'food', amount: '', note: '', date: L.today() }, categories: L.categories.filter(c => c.type === 'expense') }); },\n  editEntry(e) {\n    const r = this.book.transactions.find(t => t.id === e.currentTarget.dataset.id); if (!r) return;\n    this.setData({ editor: true, form: Object.assign({}, r, { amount: (r.amount / 100).toFixed(2) }), categories: L.categories.filter(c => c.type === r.type) });\n  },\n  closeEditor() { this.setData({ editor: false, budgetEditor: false }); },\n  noop() {},\n  setType(e) { const type = e.currentTarget.dataset.type; if (type === this.data.form.type) return; const categories = L.categories.filter(c => c.type === type); this.setData({ 'form.type': type, 'form.category': categories[0].id, categories }); },\n  setCategory(e) { this.setData({ 'form.category': e.currentTarget.dataset.id }); },\n  inputAmount(e) { this.setData({ 'form.amount': e.detail.value }); },\n  inputNote(e) { this.setData({ 'form.note': e.detail.value }); },\n  inputDate(e) { this.setData({ 'form.date': e.detail.value }); },\n  saveEntry() {\n    if (!this.data.editor) return;\n    let candidate;\n    try { candidate = L.saveEntry(this.book, this.data.form); }\n    catch (e) { wx.showToast({ title: e.message, icon: 'none' }); return; }\n    const finish = book => { if (this.commit(book)) { if (typeof wx.hideKeyboard === 'function') wx.hideKeyboard(); this.setData({ editor: false, budgetEditor: false, tab: 'stats', month: this.data.form.date.slice(0,7), query: '', filter: 'all', form: {} }); this.refresh(); wx.pageScrollTo({ scrollTop: 0, duration: 150 }); wx.showToast({ title: '记好啦，喵～', icon: 'success' }); } };\n    finish(candidate);\n  },\n  deleteEntry() { wx.showModal({ title: '删除这笔记录？', content: '删除后无法恢复，统计数据会同步更新。', confirmText: '删除', confirmColor: '#c16b58', success: result => { if (result.confirm && this.commit(Object.assign({}, this.book, { transactions: this.book.transactions.filter(t => t.id !== this.data.form.id) }))) { this.setData({ editor: false }); wx.showToast({ title: '已删除', icon: 'success' }); } } }); },\n  openBudget() { this.setData({ budgetEditor: true, budgetInput: (this.book.budget / 100).toFixed(2) }); },\n  inputBudget(e) { this.setData({ budgetInput: e.detail.value }); },\n  saveBudget() { try { const value = String(this.data.budgetInput).trim(); const budget = /^0+(\\.0{1,2})?$/.test(value) ? 0 : L.parseAmount(value); if (this.commit(Object.assign({}, this.book, { budget }))) { this.setData({ budgetEditor: false }); wx.showToast({ title: '预算已更新', icon: 'success' }); } } catch (e) { wx.showToast({ title: e.message, icon: 'none' }); } },\n  clearBook() { wx.showModal({ title: '清空' + this.data.accountName + '账单？', content: '当前账本的全部收支记录将删除，月预算会保留。此操作无法恢复，建议先导出当前账本。另一个账本不受影响。', confirmText: '确认清空', confirmColor: '#c16b58', success: result => { if (result.confirm && this.commit(Object.assign(L.empty(), { budget: this.book.budget }))) wx.showToast({ title: '当前账本已清空', icon: 'success' }); } }); },\n  exportBook() {\n    const filename = 'meow-ledger-' + this.data.account + '-' + L.today() + '.csv';\n    const filePath = wx.env.USER_DATA_PATH + '/' + filename;\n    wx.getFileSystemManager().writeFile({ filePath, data: L.csv(this.book, this.data.accountName), encoding: 'utf8', success: () => {\n      if (typeof wx.shareFileMessage === 'function') wx.shareFileMessage({ filePath, fileName: filename, fail: e => { if (!/cancel/.test(e.errMsg || '')) wx.showToast({ title: '请重试或检查存储空间', icon: 'none' }); } });\n      else wx.setClipboardData({ data: L.csv(this.book, this.data.accountName), success: () => wx.showToast({ title: '账单已复制，可粘贴到表格', icon: 'none' }) });\n    }, fail: () => wx.showToast({ title: '导出失败，请检查存储空间', icon: 'none' }) });\n  },\n  showPrivacy() { wx.showModal({ title: '给你安心的小账本', content: '个人消费与公账分别记账、统计和设置预算，均仅保存在当前设备的 浏览器本地存储中。公账是本机独立账本，不提供多人共享。不上传服务器，也不读取微信支付账单。清除缓存、清除网站数据或更换设备可能导致数据丢失，记得分别导出两个账本。', showCancel: false, confirmText: '知道啦', confirmColor: '#65744d' }); },\n  installHelp() { wx.showModal({ title: '把账本放到手机桌面', content: 'iPhone：用 Safari 打开本页面，点击分享按钮，再选择「添加到主屏幕」。如有「作为网页 App 打开」，请保持开启。\\n\\n添加后点桌面图标即可使用。首次联网加载完成后可离线记账；账单保存在这台设备中。', showCancel: false, confirmText: '知道啦' }); },\n  onShareAppMessage() { return { title: '喵喵账本｜把生活记成喜欢的样子', path: '/pages/index/index' }; }\n});\n"};
